-- OTOTR EXPENSE SHARE CALCULATION RPC CANDIDATE
create or replace function finance_private.current_expense_share_calculator_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_expense_share_authorization(p_actor_id uuid,p_expense_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_private.resolve_approved_expense_allocation_context(p_expense_id uuid,p_distribution_method text,p_distribution_rule_reference text) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_api.authorize_expense_share_calculation(p_expense_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when auth.uid() is null or p_permission<>'finance.expenses.calculate' then null::jsonb else finance_private.resolve_expense_share_authorization(auth.uid(),p_expense_id,p_permission) end$$;

create or replace function finance_api.commit_expense_share_calculation(p_actor_id uuid,p_expense_id uuid,p_distribution_method text,p_distribution_rule_reference text,p_expected_version bigint,p_idempotency_key text,p_input_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare e finance.pass_through_expenses%rowtype;c jsonb;v_existing jsonb;v_targets jsonb;v_target_count integer;v_basis_total numeric(24,8);v_snapshot text;v_payload jsonb;v_previous text;v_audit text;v_shares jsonb;v_new_version bigint;
begin
 if not finance_private.current_expense_share_calculator_is_trusted() then raise exception using errcode='42501',message='trusted expense share calculator required';end if;
 if p_distribution_method not in ('FIXED','EQUAL','QUANTITY') then raise exception using errcode='0A000',message='REVENUE and CUSTOM allocation methods are disabled';end if;
 if pg_catalog.length(pg_catalog.btrim(coalesce(p_distribution_rule_reference,''))) not between 1 and 200 or pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_expected_version<1 or p_input_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='expense share command invalid';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('expense-share:'||p_expense_id::text,0));select * into e from finance.pass_through_expenses where id=p_expense_id for update;if not found then raise exception using errcode='P0002',message='expense not found';end if;
 select om.payload into v_existing from finance.outbox_messages om where om.legal_entity_id=e.legal_entity_id and om.event_type='PASS_THROUGH_EXPENSE_SHARES_CALCULATED' and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if v_existing->>'intentHash'=p_input_hash then return v_existing||pg_catalog.jsonb_build_object('outcome','REPLAY');end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if e.version<>p_expected_version or e.status not in ('DRAFT','CALCULATED') then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 c:=finance_private.resolve_approved_expense_allocation_context(p_expense_id,p_distribution_method,p_distribution_rule_reference);if c is null or c->>'allowed'<>'true' or c->>'distributionMethod'<>p_distribution_method or c->>'distributionRuleReference'<>p_distribution_rule_reference or coalesce(c->>'policyVersion','')='' or pg_catalog.jsonb_typeof(c->'targets')<>'array' or pg_catalog.jsonb_array_length(c->'targets')<1 then raise exception using errcode='42501',message='approved expense allocation policy required';end if;
 if exists(select 1 from pg_catalog.jsonb_array_elements(c->'targets') t where pg_catalog.jsonb_typeof(t)<>'object' or (select pg_catalog.array_agg(k order by k) from pg_catalog.jsonb_object_keys(t) k) is distinct from array['basisValue','branchId','dealerAccountId']::text[] or coalesce(t->>'dealerAccountId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(t->>'branchId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(t->>'basisValue','')!~'^(0|[1-9][0-9]*)(\.[0-9]{1,8})?$') then raise exception using errcode='22023',message='approved allocation targets invalid';end if;
 select pg_catalog.count(*),pg_catalog.sum((t->>'basisValue')::numeric) into v_target_count,v_basis_total from pg_catalog.jsonb_array_elements(c->'targets') t;if v_target_count<>(select pg_catalog.count(*) from (select distinct t->>'dealerAccountId',t->>'branchId' from pg_catalog.jsonb_array_elements(c->'targets') t) q) or v_target_count<>pg_catalog.jsonb_array_length(e.allocation_policy->'targetScopes') then raise exception using errcode='23514',message='allocation target scope mismatch';end if;
 if exists(select 1 from pg_catalog.jsonb_array_elements(c->'targets') t where not exists(select 1 from pg_catalog.jsonb_array_elements(e.allocation_policy->'targetScopes') s where s->>'dealerAccountId'=t->>'dealerAccountId' and s->>'branchId'=t->>'branchId') or not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=(t->>'dealerAccountId')::uuid and b.id=(t->>'branchId')::uuid and da.legal_entity_id=e.legal_entity_id and da.currency_code=e.currency_code and da.status='ACTIVE' and b.status='ACTIVE')) then raise exception using errcode='42501',message='allocation target scope denied';end if;
 if (p_distribution_method='FIXED' and v_basis_total<>e.distributable_amount) or (p_distribution_method in ('EQUAL','QUANTITY') and (v_basis_total<=0 or exists(select 1 from pg_catalog.jsonb_array_elements(c->'targets') t where p_distribution_method='QUANTITY' and (t->>'basisValue')::numeric<=0))) then raise exception using errcode='23514',message='allocation basis invalid for method';end if;
 delete from finance.expense_shares where pass_through_expense_id=e.id and accrual_id is null;
 with targets as(select (t->>'dealerAccountId')::uuid dealer_id,(t->>'branchId')::uuid branch_id,(t->>'basisValue')::numeric basis_value,case when p_distribution_method='EQUAL' then 1::numeric else (t->>'basisValue')::numeric end weight from pg_catalog.jsonb_array_elements(c->'targets') t),base as(select *,pg_catalog.sum(weight)over() total_weight from targets),floors as(select *,pg_catalog.floor(e.distributable_net_amount*100000000*weight/total_weight)/100000000 net_floor,(e.distributable_net_amount*100000000*weight/total_weight)-pg_catalog.floor(e.distributable_net_amount*100000000*weight/total_weight) net_fraction,pg_catalog.floor(e.distributable_tax_amount*100000000*weight/total_weight)/100000000 tax_floor,(e.distributable_tax_amount*100000000*weight/total_weight)-pg_catalog.floor(e.distributable_tax_amount*100000000*weight/total_weight) tax_fraction from base),ranked as(select *,pg_catalog.row_number()over(order by net_fraction desc,dealer_id,branch_id) net_rank,pg_catalog.row_number()over(order by tax_fraction desc,dealer_id,branch_id) tax_rank,pg_catalog.round((e.distributable_net_amount-pg_catalog.sum(net_floor)over())*100000000)::bigint net_units,pg_catalog.round((e.distributable_tax_amount-pg_catalog.sum(tax_floor)over())*100000000)::bigint tax_units from floors),amounts as(select *,net_floor+case when net_rank<=net_units then 0.00000001 else 0 end net_amount,tax_floor+case when tax_rank<=tax_units then 0.00000001 else 0 end tax_amount from ranked) insert into finance.expense_shares(pass_through_expense_id,dealer_account_id,branch_id,allocation_method,distribution_rule_reference,basis_value,allocation_rate,net_amount,tax_amount,share_amount,allocation_order,snapshot_hash,created_by,correlation_id) select e.id,dealer_id,branch_id,p_distribution_method,p_distribution_rule_reference,basis_value,pg_catalog.round(weight/total_weight,8),net_amount,tax_amount,net_amount+tax_amount,pg_catalog.row_number()over(order by dealer_id,branch_id),p_input_hash,p_actor_id,p_correlation_id from amounts order by dealer_id,branch_id;
 if (select pg_catalog.sum(net_amount)<>e.distributable_net_amount or pg_catalog.sum(tax_amount)<>e.distributable_tax_amount or pg_catalog.sum(share_amount)<>e.distributable_amount from finance.expense_shares where pass_through_expense_id=e.id) then raise exception using errcode='23514',message='expense share control totals mismatch';end if;
 select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('dealerAccountId',s.dealer_account_id,'branchId',s.branch_id,'totals',pg_catalog.jsonb_build_object('currency',e.currency_code,'netAmount',s.net_amount::text,'taxAmount',s.tax_amount::text,'grossAmount',s.share_amount::text)) order by s.allocation_order) into v_shares from finance.expense_shares s where s.pass_through_expense_id=e.id;
 v_snapshot:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_input_hash||':'||(c->>'policyVersion')||':'||v_shares::text,'UTF8'),'sha256'),'hex');update finance.expense_shares set snapshot_hash=v_snapshot where pass_through_expense_id=e.id;v_new_version:=e.version+1;update finance.pass_through_expenses set allocation_policy=pg_catalog.jsonb_build_object('status','CALCULATED','method',p_distribution_method,'ruleReference',p_distribution_rule_reference,'policyVersion',c->>'policyVersion','targetScopes',e.allocation_policy->'targetScopes','snapshotHash',v_snapshot),status='CALCULATED',version=v_new_version,correlation_id=p_correlation_id where id=e.id and version=p_expected_version;
 v_payload:=pg_catalog.jsonb_build_object('expenseId',e.id,'inputHash',v_snapshot,'intentHash',p_input_hash,'currencyCode',e.currency_code,'shares',v_shares,'controlNet',e.distributable_net_amount::text,'controlTax',e.distributable_tax_amount::text,'controlGross',e.distributable_amount::text,'version',v_new_version,'idempotencyKey',p_idempotency_key);insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(e.legal_entity_id,'finance.expense','PASS_THROUGH_EXPENSE_SHARES_CALCULATED','PASS_THROUGH_EXPENSE',e.id,v_new_version,v_payload,v_snapshot,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||e.legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=e.legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||e.id::text||':PASS_THROUGH_EXPENSE_SHARES_CALCULATED:'||v_snapshot||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(e.legal_entity_id,p_actor_id,'USER','PASS_THROUGH_EXPENSE_SHARES_CALCULATED','PASS_THROUGH_EXPENSE',e.id,'ALLOW',v_snapshot,v_previous,v_audit,pg_catalog.jsonb_build_object('method',p_distribution_method,'ruleReference',p_distribution_rule_reference,'policyVersion',c->>'policyVersion','shareCount',v_target_count,'version',v_new_version),p_correlation_id);
 return v_payload||pg_catalog.jsonb_build_object('outcome','CALCULATED');
end$$;
revoke all on function finance_private.current_expense_share_calculator_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_expense_share_authorization(uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_private.resolve_approved_expense_allocation_context(uuid,text,text) from public,anon,authenticated;revoke all on function finance_api.authorize_expense_share_calculation(uuid,text) from public,anon;grant execute on function finance_api.authorize_expense_share_calculation(uuid,text) to authenticated;revoke all on function finance_api.commit_expense_share_calculation(uuid,uuid,text,text,bigint,text,text,uuid) from public,anon,authenticated;
